<template><PageWrapper><div class="mb-4 flex justify-between"><span class="text-lg font-bold">权益档位管理</span><el-button type="primary" @click="open()">新增档位</el-button></div><el-alert title="停用只影响后续权益办理，不会追溯修改已发放权益的档位或价格快照。" type="info" :closable="false" class="mb-4"/><el-table :data="rows" border v-loading="loading"><el-table-column label="品牌"><template #default="{row}">{{ brandName(row.brandId) }}</template></el-table-column><el-table-column prop="tierCode" label="代码"/><el-table-column prop="tierName" label="名称"/><el-table-column prop="configuredAmount" label="金额"/><el-table-column label="价格档"><template #default="{row}">{{ levelName(row.pricingLevelCode) }}</template></el-table-column><el-table-column prop="rankValue" label="等级"/><el-table-column prop="sortNo" label="排序"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-dialog v-model="visible" :title="form.id?'编辑档位':'新增档位'" width="520px" destroy-on-close><el-form label-width="90px"><el-form-item label="品牌"><el-select v-model="form.brandId" filterable class="w-full" @change="loadLevels"><el-option v-for="brand in brands" :key="brand.value" :label="brand.label" :value="String(brand.value)"/></el-select></el-form-item><el-form-item label="档位代码"><el-input v-model="form.tierCode"/></el-form-item><el-form-item label="档位名称"><el-input v-model="form.tierName"/></el-form-item><el-form-item label="配置金额"><el-input-number v-model="form.configuredAmount" :min="0" :precision="2"/></el-form-item><el-form-item label="价格档"><el-select v-model="form.pricingLevelCode" class="w-full"><el-option v-for="level in levels" :key="level.value" :label="level.desc" :value="level.value"/></el-select></el-form-item><el-form-item label="等级 / 排序"><el-input-number v-model="form.rankValue" :min="0"/><el-input-number v-model="form.sortNo" :min="0" class="ml-3"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></PageWrapper></template>
<script setup>import {ref,onMounted} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import PageWrapper from '@/components/PageWrapper.vue';import brandApi from '@/api/gms/brand.js';import dictApi from '@/api/system/dict.js';import api from '@/api/ums/memberBenefitTier.js';const rows=ref([]),brands=ref([]),memberTypes=ref([]),levels=ref([]),visible=ref(false),loading=ref(false),form=ref({});const brandName=id=>brands.value.find(brand=>String(brand.value)===String(id))?.label||id;const levelName=code=>memberTypes.value.find(level=>level.value===code)?.desc||code;const load=async()=>{loading.value=true;try{const r=await api.list();rows.value=r.data||r}catch(e){}finally{loading.value=false}};const loadLevels=async()=>{const r=await api.pricing(form.value.brandId);const codes=r.data?.levelCodes||r.levelCodes||[];levels.value=memberTypes.value.filter(level=>codes.includes(level.value))};const open=async row=>{form.value=row?{...row}:{brandId:'',tierCode:'',tierName:'',configuredAmount:0,pricingLevelCode:'',rankValue:0,sortNo:0,enabled:true,remark:''};if(form.value.brandId)await loadLevels();visible.value=true};const save=async()=>{await api.save(form.value);ElMessage.success('档位已保存');visible.value=false;load()};const remove=async row=>{await ElMessageBox.confirm(`删除档位 ${row.tierName}？`, '确认删除',{type:'warning'});await api.remove(row.id);ElMessage.success('档位已删除');load()};onMounted(async()=>{const [brandRes,dict]=await Promise.all([brandApi.getSelect(),dictApi.loadDict(['memberType'])]);brands.value=brandRes.data||brandRes;memberTypes.value=(dict.memberType||[]).filter(level=>level.value!=='MEMBER');load()})</script>
